INSERT INTO products (id, name, description, price, images_json, category, stock, data_ai_hint) VALUES
('prod_001', 'Quantum Watch', 'Experience precision timekeeping with our flagship smartwatch. Featuring an always-on AMOLED display, comprehensive health and fitness tracking, and a battery that lasts up to 7 days on a single charge. The water-resistant titanium case ensures durability for any adventure.', 299.99, '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Watches', 25, 'smartwatch'),
('prod_002', 'Aura Noise-Cancelling Headphones', 'Immerse yourself in pure sound with the Aura over-ear headphones. Industry-leading active noise cancellation silences the world around you, while custom-tuned drivers deliver rich, detailed audio. Enjoy up to 30 hours of wireless playback with plush memory foam earcups.', 349.50, '["https://images.unsplash.com/photo-1505740420928-5e560c06d30e?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png","https://placehold.co/600x600.png"]', 'Audio', 15, 'headphones'),
('prod_003', 'Apex Pro Ultra Laptop', 'Engineered for power users and creatives. Powered by the latest generation multi-core processor and dedicated graphics, the Apex Pro Ultra handles demanding tasks like video editing and 3D modeling with ease. The stunning 4K OLED display brings your work to life.', 1899.00, '["https://images.unsplash.com/photo-1517336714731-489689fd1ca8?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Laptops', 10, 'premium laptop'),
('prod_004', 'Titan Gaming Laptop', 'Dominate the competition with the Titan Gaming Laptop. Boasts a high-refresh-rate display, a top-tier graphics card, and an advanced cooling system. The customizable RGB keyboard and immersive audio will elevate your gaming experience to new heights.', 2100.50, '["https://images.unsplash.com/photo-1593642702821-c8da6771f0c6?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png","https://placehold.co/600x600.png"]', 'Laptops', 5, 'gaming laptop'),
('prod_005', 'Galaxy Pro Smartphone', 'Capture life in stunning detail with the Galaxy Pro. Its professional-grade camera system, brilliant dynamic display, and powerful processor make it a leader in its class. Features an intelligent S-Pen for ultimate productivity and creativity. 5G ready.', 1199.99, '["https://images.unsplash.com/photo-1601784551446-20c9e07cdbf1?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Smartphones', 30, 'modern smartphone'),
('prod_006', 'Pixel Perfect Smartphone', 'The smart choice for a smartphone. Renowned for its exceptional camera powered by AI, clean software experience, and tight integration with Google services. Get the best of Android with timely updates and helpful features that anticipate your needs.', 899.00, '["https://images.unsplash.com/photo-1610945415295-d9bbf067e59c?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Smartphones', 22, 'sleek smartphone'),
('prod_007', 'Minimalist Digital Watch', 'Simplicity meets sophistication. This digital watch features a clean, easy-to-read display in a slim and lightweight case. Perfect for everyday wear, it offers essential features like an alarm, stopwatch, and backlight in an understated design.', 150.00, '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?q=80&w=600&auto=format&fit=crop"]', 'Watches', 40, 'minimalist watch'),
('prod_008', 'Creator Pro Laptop', 'The ultimate tool for creators. This laptop is built to handle demanding creative workflows with its color-accurate display, powerful GPU, and extensive port selection. Whether you are into video editing, 3D rendering, or graphic design, this machine has you covered.', 2500.00, '["https://images.unsplash.com/photo-1589561253898-768105ca91a8?q=80&w=600&auto=format&fit=crop","https://placehold.co/600x600.png"]', 'Laptops', 8, 'powerful laptop');
